SELECT A.MTG_ITOAGD_SE_CD AS MTG_ITOAGD_SE_CD, /* 회의안건구분코드 */ A.MTG_ITOAGD_TTL_CN AS MTG_ITOAGD_TTL_CN, /* 회의안건제목내용 */ A.MTG_ITOAGD_MAIN_CN AS MTG_ITOAGD_MAIN_CN, /* 회의안건주요내용 */
A.MTG_ITOAGD_MNG_NO AS MTG_ITOAGD_MNG_NO, /* 회의안건관리번호 */ A.MTG_NO AS MTG_NO /* 회의번호 */ FROM ACA621 A /* 위원회회의안건 */ WHERE A.MTG_NO = #{MTG_NO}

